function applyChromeTheme(theme: ThemeVariant, mode: "light" | "dark"): void {
  const tokensCss =
    theme === "canvas"
      ? canvasTokensCss
      : theme === "canvasHighContrast"
        ? canvasHighContrastTokensCss
        : adaptiveTokensCss;
  // Without `PREVIEW_SCHEME_FORCE_CSS`, the chrome's own buttons/text stay pinned to the OS
  // `prefers-color-scheme` (see that constant's comment) even though `colorScheme` below is set
  // explicitly — only the native-CSS background rules that key off `color-scheme` directly would
  // follow the toggle, leaving everything else stuck on the OS default. `TRAY_SCHEME_FORCE_CSS`
  // pins the tray's own forced-dark scope; re-declaring `tokensCss` a second time under
  // `#theme-tray` (see that constant's comment) is what makes every token the tray's descendants
  // inherit actually resolve dark, not just the two control variables.
  chromeThemeStyle.textContent = [
    tokensCss,
    PREVIEW_SCHEME_FORCE_CSS,
    TRAY_SCHEME_FORCE_CSS,
    tokensCss.replaceAll(":root", "#theme-tray"),
  ].join("\n");

