let refreshGeneration = 0;
// Covers `plugin-logos` (a real dependency for any scaffolded project) and the icon packages
// `build-canvas-rce.ts` vendors into `node_modules` purely so this docs-hosted preview's "None
// (inline)" provider doesn't have to hit a CDN for `::name` autocomplete/picker glyphs.
const localAssetUrls = import.meta.glob<string>(
  "/node_modules/@pantoken/plugin-{logos,simple-icons,lucide-lab,custom-icons}/dist/**/*.css",
  { eager: true, import: "default", query: "?url" },
);

function buildSelectedAssetUrl(file: CdnFile): string {
  if (providerSelect.value !== LOCAL_PROVIDER_ID) {
    return buildFileUrl(file, providerSelect.value);
  }
  const localUrl = localAssetUrls[`/node_modules/${file.package}/${file.path}`];
  return localUrl ?? buildFileUrl(file);
}

